:root {
  --bg: #171310;
  --panel: #221d1a;
  --panel-strong: #2d2421;
  --wood: #7a4d2b;
  --gold: #f1d27a;
  --mint: #8fe5c1;
  --rose: #f49bb5;
  --blue: #9ed4ff;
  --white: #f7f1ea;
  --shadow: rgba(0, 0, 0, 0.32);
}

* { box-sizing: border-box; }
html, body {
  margin: 0;
  height: 100%;
  background: radial-gradient(circle at top, #2d221f 0%, var(--bg) 45%, #120f10 100%);
  color: var(--white);
  font-family: "Trebuchet MS", "Segoe UI", sans-serif;
}
body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}
.game-shell {
  width: min(1200px, calc(100vw - 24px));
  display: grid;
  grid-template-columns: minmax(0, 1fr) 270px;
  grid-template-rows: auto auto;
  gap: 16px;
  padding: 16px;
  background: rgba(12, 10, 11, 0.7);
  border: 2px solid rgba(255,255,255,0.15);
  border-radius: 18px;
  box-shadow: 0 18px 40px rgba(0,0,0,0.4);
}
.topbar {
  grid-column: 1 / 3;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: rgba(34, 26, 24, 0.8);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 14px;
  padding: 14px 18px;
}
.title { font-size: clamp(1.4rem, 2vw, 2.3rem); font-weight: 900; letter-spacing: 0.14em; color: var(--gold); }
.subtitle { font-size: 0.72rem; letter-spacing: 0.18em; text-transform: uppercase; color: #edc9a0; opacity: 0.9; }
.hud {
  display: flex;
  flex-wrap: wrap;
  justify-content: end;
  gap: 10px;
}
.stat {
  min-width: 72px;
  padding: 8px 10px;
  border-radius: 10px;
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.06);
  display: flex;
  flex-direction: column;
  align-items: center;
}
.stat span { font-size: 0.62rem; letter-spacing: 0.12em; text-transform: uppercase; color: #d8d0c8; }
.stat strong { font-size: 1.2rem; color: var(--white); }
.game-wrap {
  background: linear-gradient(180deg, #2b1d1a 0%, #1a1514 100%);
  border-radius: 18px;
  border: 1px solid rgba(255,255,255,0.06);
  position: relative;
  overflow: hidden;
}
canvas {
  display: block;
  width: 100%;
  height: auto;
  background: linear-gradient(#2a1b1d, #1d1414);
  image-rendering: pixelated;
}
.sidebar {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.panel {
  background: var(--panel);
  border-radius: 12px;
  border: 1px solid rgba(255,255,255,0.08);
  padding: 12px 14px;
}
.panel h3 {
  margin: 0 0 8px;
  color: var(--gold);
  font-size: 0.8rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.panel ul {
  margin: 0;
  padding-left: 16px;
  color: #f0dfd3;
  line-height: 1.8;
  font-size: 0.82rem;
}
#host {
  color: var(--mint);
  font-weight: 700;
  font-size: 1rem;
}
.log-panel {
  flex: 1;
  min-height: 160px;
}
#log {
  color: #f0dfd3;
  line-height: 1.6;
  font-size: 0.9rem;
}

@media (max-width: 860px) {
  .game-shell {
    grid-template-columns: 1fr;
  }
  .topbar {
    grid-column: 1;
    flex-direction: column;
    align-items: flex-start;
  }
  .sidebar {
    order: 3;
  }
}

const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');

const scoreEl = document.getElementById('score');
const reputationEl = document.getElementById('reputation');
const spiritEl = document.getElementById('spirit');
const timeEl = document.getElementById('time');
const logEl = document.getElementById('log');
const hostEl = document.getElementById('host');

const TILE = 32;
const cols = 30;
const rows = 17;
const world = {
  width: cols * TILE,
  height: rows * TILE,
};

const state = {
  score: 0,
  reputation: 35,
  spirit: 100,
  timeLeft: 90,
  phase: 'day',
  tick: 0,
  message: 'The inn hums, awaiting a little mischief.',
  currentHost: 'Ghost drift',
  ghostMode: true,
  player: {
    x: 220,
    y: 210,
    vx: 0,
    vy: 0,
    speed: 140,
    radius: 14,
    possessing: null,
    bodyCooldown: 0,
    form: 'ghost'
  },
  npcs: [
    { id: 'mom', name: 'Mara', role: 'Innkeeper', x: 530, y: 150, color: '#f6d4d7', personality: 'soft', body: 'mother', mood: 55, task: 'polish the dining room', sprite: { w: 20, h: 26 }, braSize: 'DD', energy: 70, baseX: 530, baseY: 150 },
    { id: 'teen', name: 'Lina', role: 'Waitress', x: 680, y: 240, color: '#f7e9b8', personality: 'playful', body: 'teen', mood: 62, task: 'carry tea trays', sprite: { w: 20, h: 26 }, braSize: 'C', energy: 75, baseX: 680, baseY: 240 },
    { id: 'kid', name: 'Toby', role: 'Kitchen helper', x: 465, y: 300, color: '#b7d5ff', personality: 'naughty', body: 'kid', mood: 60, task: 'sneak treats', sprite: { w: 18, h: 24 }, energy: 80, baseX: 465, baseY: 300 },
    { id: 'dad', name: 'Harlan', role: 'Chef', x: 760, y: 330, color: '#dbbfa8', personality: 'busy', body: 'dad', mood: 50, task: 'stir the stew', sprite: { w: 22, h: 26 }, energy: 68, baseX: 760, baseY: 330 },
  ],
  rooms: [
    { name: 'Front Room', x: 70, y: 65, w: 270, h: 160 },
    { name: 'Kitchen', x: 380, y: 90, w: 310, h: 250 },
    { name: 'Stair Hall', x: 700, y: 90, w: 170, h: 160 },
    { name: 'Guest Rooms', x: 120, y: 295, w: 260, h: 150 },
    { name: 'Courtyard', x: 430, y: 360, w: 400, h: 120 }
  ],
  tasks: {
    good: ['fix the tea service', 'sweep the lobby', 'calm the guests', 'prepare the dinner table'],
    naughty: ['tease the waitress', 'peek under the towel', 'sneak a little touch', 'slip into a soft body']
  }
};

const keyState = {};
const pressed = new Set();

function clamp(value, min, max) { return Math.max(min, Math.min(max, value)); }

function setLog(msg) {
  state.message = msg;
  logEl.textContent = msg;
}

function updateHud() {
  scoreEl.textContent = state.score;
  reputationEl.textContent = state.reputation;
  spiritEl.textContent = Math.round(state.spirit);
  timeEl.textContent = Math.ceil(state.timeLeft);
  hostEl.textContent = state.currentHost;
}

function nearestNpc() {
  let best = null;
  let bestDist = Infinity;
  for (const npc of state.npcs) {
    const dist = Math.hypot(state.player.x - npc.x, state.player.y - npc.y);
    if (dist < bestDist && dist < 90) {
      best = npc;
      bestDist = dist;
    }
  }
  return best;
}

function getHostName() {
  if (state.player.possessing) {
    const npc = state.player.possessing;
    return `${npc.name} (${npc.role})`;
  }
  return state.ghostMode ? 'Ghost drift' : 'Own body';
}

function handlePossession() {
  if (state.player.bodyCooldown > 0) return;
  const npc = nearestNpc();
  if (!npc) {
    setLog('No one is close enough for a playful possession.');
    return;
  }

  if (state.player.possessing && state.player.possessing.id === npc.id) {
    state.player.possessing = null;
    state.player.form = 'ghost';
    state.currentHost = 'Ghost drift';
    state.player.x = npc.x + 10;
    state.player.y = npc.y + 14;
    setLog(`The spirit slips free from ${npc.name}.`);
    return;
  }

  state.player.possessing = npc;
  state.player.form = 'body';
  state.player.x = npc.x;
  state.player.y = npc.y;
  state.currentHost = getHostName();
  state.spirit = clamp(state.spirit - 6, 0, 100);
  setLog(`${npc.name} is now your body for a sly little prank.`);
  state.player.bodyCooldown = 0.7;
}

function swapBodies() {
  if (state.player.bodyCooldown > 0) return;
  if (state.player.possessing) {
    const current = state.player.possessing;
    state.player.possessing = null;
    state.player.form = 'ghost';
    const target = state.npcs.find(npc => npc.id !== current.id && Math.hypot(npc.x - current.x, npc.y - current.y) < 150);
    if (!target) {
      setLog('No nearby target for a body swap.');
      return;
    }
    const tempX = current.x;
    const tempY = current.y;
    current.x = target.x;
    current.y = target.y;
    target.x = tempX;
    target.y = tempY;
    state.score += 30;
    state.reputation = clamp(state.reputation - 2, 0, 100);
    setLog(`A mischievous swap sends ${current.name} into ${target.name}'s shoes.`);
    state.player.bodyCooldown = 1.2;
    return;
  }

  const target = nearestNpc();
  if (!target) {
    setLog('No target is close enough to swap with.');
    return;
  }
  const originalX = target.x;
  const originalY = target.y;
  target.x = state.player.x;
  target.y = state.player.y;
  state.player.x = originalX;
  state.player.y = originalY;
  state.player.possessing = target;
  state.player.form = 'body';
  state.currentHost = getHostName();
  state.score += 25;
  setLog(`The ghost hijacks ${target.name}'s form in a sudden body swap.`);
  state.player.bodyCooldown = 0.8;
}

function doHelpfulAction() {
  const spiritCost = 10;
  if (state.spirit < spiritCost) {
    setLog('The spirit is too weak for any helpful mischief.');
    return;
  }

  const task = state.tasks.good[Math.floor(Math.random() * state.tasks.good.length)];
  state.score += 15;
  state.reputation = clamp(state.reputation + 8, 0, 100);
  state.spirit = clamp(state.spirit - spiritCost, 0, 100);
  setLog(`You help the inn by ${task}. The family approves.`);

  for (const npc of state.npcs) {
    npc.mood = clamp(npc.mood + 9, 0, 100);
  }
}

function doNaughtyAction() {
  const target = nearestNpc();
  if (!target) {
    setLog('No nearby target to tease with a naughty little ghost trick.');
    return;
  }

  const stunt = state.tasks.naughty[Math.floor(Math.random() * state.tasks.naughty.length)];
  state.score += 20;
  state.reputation = clamp(state.reputation - 7, 0, 100);
  state.spirit = clamp(state.spirit + 8, 0, 100);
  target.mood = clamp(target.mood - 12, 0, 100);
  setLog(`You ${stunt} while ${target.name} squints in confusion.`);
}

function movePlayer(dt) {
  let dx = 0;
  let dy = 0;
  if (keyState['KeyW'] || keyState['ArrowUp']) dy -= 1;
  if (keyState['KeyS'] || keyState['ArrowDown']) dy += 1;
  if (keyState['KeyA'] || keyState['ArrowLeft']) dx -= 1;
  if (keyState['KeyD'] || keyState['ArrowRight']) dx += 1;

  const length = Math.hypot(dx, dy) || 1;
  if (state.player.possessing) {
    const npc = state.player.possessing;
    const targetX = clamp(npc.x + (dx / length) * 70 * dt, 140, world.width - 120);
    const targetY = clamp(npc.y + (dy / length) * 70 * dt, 110, world.height - 100);
    npc.x = targetX;
    npc.y = targetY;
    state.player.x = npc.x;
    state.player.y = npc.y;
  } else {
    state.player.x = clamp(state.player.x + (dx / length) * state.player.speed * dt, 30, world.width - 30);
    state.player.y = clamp(state.player.y + (dy / length) * state.player.speed * dt, 30, world.height - 30);
  }

  if (state.player.possessing && dx === 0 && dy === 0) {
    const npc = state.player.possessing;
    if (Math.random() < 0.08) {
      npc.mood = clamp(npc.mood + 3, 0, 100);
    }
  }
}

function updateNpcs(dt) {
  for (const npc of state.npcs) {
    const driftX = Math.sin((state.tick + npc.x) * 0.035) * 18;
    const driftY = Math.cos((state.tick + npc.y) * 0.028) * 16;
    npc.x = clamp(npc.x + driftX * dt * 0.7, 120, world.width - 120);
    npc.y = clamp(npc.y + driftY * dt * 0.7, 90, world.height - 90);

    if (state.player.possessing && npc.id === state.player.possessing.id) continue;

    const dist = Math.hypot(state.player.x - npc.x, state.player.y - npc.y);
    if (dist < 100) {
      npc.mood = clamp(npc.mood + 0.5 * dt, 0, 100);
    } else {
      npc.mood = clamp(npc.mood - 0.12 * dt, 0, 100);
    }
  }
}

function updateGame(dt) {
  state.tick += dt;
  state.timeLeft -= dt;
  state.phase = state.timeLeft > 45 ? 'day' : 'night';

  if (state.player.bodyCooldown > 0) {
    state.player.bodyCooldown = Math.max(0, state.player.bodyCooldown - dt);
  }

  movePlayer(dt);
  updateNpcs(dt);

  if (state.player.possessing) {
    state.currentHost = getHostName();
  } else {
    state.currentHost = state.ghostMode ? 'Ghost drift' : 'Your body';
  }

  if (state.timeLeft <= 0) {
    const ending = state.reputation >= 50 ? 'The inn becomes your favorite haunted home, and the family loves your ghostly touch.' : 'The inn survives, but the family still thinks you are a troublesome spirit.';
    setLog(`Night falls. ${ending}`);
  }

  if (Math.random() < 0.01) {
    const npc = state.npcs[Math.floor(Math.random() * state.npcs.length)];
    npc.mood = clamp(npc.mood + 4, 0, 100);
  }

  if (state.player.possessing) {
    const npc = state.player.possessing;
    if (Math.random() < 0.03) {
      state.score += 2;
      npc.mood = clamp(npc.mood - 1, 0, 100);
    }
  }

  if (state.spirit < 25 && !state.player.possessing) {
    state.spirit = clamp(state.spirit + 4 * dt, 0, 100);
  }

  updateHud();
}

function drawBackground() {
  const sky = state.phase === 'night' ? '#1a1b2d' : '#e7af6d';
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = '#2f211d';
  ctx.fillRect(0, 90, canvas.width, 420);

  for (const room of state.rooms) {
    ctx.fillStyle = room.name === 'Kitchen' ? '#8d5d38' : room.name === 'Courtyard' ? '#6d8d62' : '#59413a';
    ctx.fillRect(room.x, room.y, room.w, room.h);
    ctx.strokeStyle = 'rgba(255,255,255,0.15)';
    ctx.strokeRect(room.x, room.y, room.w, room.h);
    ctx.fillStyle = '#f0d8bc';
    ctx.font = '12px sans-serif';
    ctx.fillText(room.name, room.x + 12, room.y + 18);
  }

  ctx.fillStyle = '#4d2f24';
  ctx.fillRect(0, 430, canvas.width, 110);

  ctx.fillStyle = '#b3905d';
  for (let i = 0; i < 14; i++) {
    ctx.fillRect(i * 70 + 30, 120 + (i % 3) * 18, 50, 8);
  }
}

function drawPlayer() {
  const p = state.player;
  if (p.possessing) {
    const npc = p.possessing;
    drawNpc(npc, true);
    return;
  }

  ctx.fillStyle = state.ghostMode ? '#e7d7ff' : '#d8f3f0';
  ctx.beginPath();
  ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#8d7ae6';
  ctx.fillRect(p.x - 8, p.y + 12, 16, 8);
}

function drawNpc(npc, isPossessed = false) {
  ctx.fillStyle = isPossessed ? '#f7d2b7' : npc.color;
  ctx.fillRect(npc.x - 10, npc.y - 14, 20, 32);
  ctx.fillStyle = '#2b1e21';
  ctx.fillRect(npc.x - 7, npc.y - 16, 14, 8);
  ctx.fillStyle = isPossessed ? '#f0d6f9' : '#ffe2ce';
  ctx.fillRect(npc.x - 11, npc.y - 12, 22, 10);
  if (npc.body === 'mother' || npc.body === 'teen') {
    ctx.fillStyle = '#f8d4dc';
    ctx.fillRect(npc.x - 9, npc.y - 4, 18, 8);
  }
  if (npc.body === 'kid') {
    ctx.fillStyle = '#ffd7a3';
    ctx.fillRect(npc.x - 8, npc.y - 3, 16, 8);
  }
  if (npc.body === 'dad') {
    ctx.fillStyle = '#eac3a0';
    ctx.fillRect(npc.x - 10, npc.y - 3, 20, 8);
  }
  ctx.fillStyle = '#1b1716';
  ctx.fillRect(npc.x - 12, npc.y + 16, 4, 12);
  ctx.fillRect(npc.x + 8, npc.y + 16, 4, 12);

  ctx.fillStyle = '#fff4c8';
  ctx.fillRect(npc.x - 12, npc.y + 26, 28, 3);

  if (isPossessed) {
    ctx.strokeStyle = '#f7dd8e';
    ctx.lineWidth = 2;
    ctx.strokeRect(npc.x - 16, npc.y - 20, 32, 48);
  }
}

function drawMoodBars() {
  state.npcs.forEach((npc) => {
    const moodColor = npc.mood > 65 ? '#8fe5c1' : npc.mood > 35 ? '#f1d27a' : '#f29a9a';
    ctx.fillStyle = 'rgba(0,0,0,0.25)';
    ctx.fillRect(npc.x - 18, npc.y - 28, 36, 5);
    ctx.fillStyle = moodColor;
    ctx.fillRect(npc.x - 18, npc.y - 28, (npc.mood / 100) * 36, 5);
  });
}

function drawPrompt() {
  ctx.fillStyle = 'rgba(12, 10, 11, 0.5)';
  ctx.fillRect(14, 14, 300, 42);
  ctx.fillStyle = '#f7f1ea';
  ctx.font = '14px sans-serif';
  const text = state.player.possessing ? 'Possessing: ' + state.player.possessing.name : 'Ghost drift: press Space to possess';
  ctx.fillText(text, 26, 40);
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawBackground();
  for (const npc of state.npcs) drawNpc(npc, false);
  drawPlayer();
  drawMoodBars();
  drawPrompt();
}

let last = performance.now();
function loop(now) {
  const dt = Math.min((now - last) / 1000, 0.033);
  last = now;

  updateGame(dt);
  render();
  requestAnimationFrame(loop);
}

window.addEventListener('keydown', (event) => {
  if (event.repeat) return;
  keyState[event.code] = true;
  if (pressed.has(event.code)) return;
  pressed.add(event.code);

  if (event.code === 'Space') {
    handlePossession();
  }
  if (event.code === 'KeyE') {
    doHelpfulAction();
  }
  if (event.code === 'KeyQ') {
    doNaughtyAction();
  }
  if (event.code === 'Digit1') {
    state.player.possessing = state.npcs[0];
    state.player.form = 'body';
    setLog(`You slip into ${state.npcs[0].name}'s skin.`);
  }
  if (event.code === 'Digit2') {
    state.player.possessing = state.npcs[1];
    state.player.form = 'body';
    setLog(`You slip into ${state.npcs[1].name}'s skin.`);
  }
  if (event.code === 'Digit3') {
    state.player.possessing = state.npcs[2];
    state.player.form = 'body';
    setLog(`You slip into ${state.npcs[2].name}'s skin.`);
  }
  if (event.code === 'Digit4') {
    state.player.possessing = state.npcs[3];
    state.player.form = 'body';
    setLog(`You slip into ${state.npcs[3].name}'s skin.`);
  }
  if (event.code === 'ShiftLeft' || event.code === 'ShiftRight') {
    state.ghostMode = !state.ghostMode;
    setLog(state.ghostMode ? 'The spirit slips into a spectral drift.' : 'You solidify into a visible body.' );
  }
});

window.addEventListener('keyup', (event) => {
  keyState[event.code] = false;
  pressed.delete(event.code);
});

updateHud();
setLog(state.message);
requestAnimationFrame(loop);

